summary: Create a dashboard
tags:
  - Dashboards
x-codeSamples:
  - label: Create a dashboard (simple) - cURL
    lang: cURL_simple
    source: |
      curl -X POST "${KIBANA_URL}/api/dashboards" \
        -H "Authorization: ApiKey ${API_KEY}" \
        -H "kbn-xsrf: true" \
        -H "Content-Type: application/json" \
        -d '{
        "title": "Web logs overview",
        "access_control": {
          "access_mode": "write_restricted"
        },
        "panels": [
          {
            "grid": {
              "x": 0,
              "y": 0,
              "w": 24,
              "h": 15
            },
            "type": "markdown",
            "config": {
              "content": "## Web logs overview\n\n&nbsp;\n\nCreated with the [Dashboards API](https://www.elastic.co/docs/api/doc/kibana) using the Kibana sample web logs dat
            }
          },
          {
            "grid": {
              "x": 24,
              "y": 0,
              "w": 12,
              "h": 5
            },
            "type": "vis",
            "config": {
              "type": "metric",
              "data_source": {
                "type": "data_view_spec",
                "index_pattern": "kibana_sample_data_logs",
                "time_field": "timestamp"
              },
              "metrics": [
                {
                  "type": "primary",
                  "operation": "count"
                }
              ]
            }
          },
          {
            "grid": {
              "x": 36,
              "y": 0,
              "w": 12,
              "h": 5
            },
            "type": "vis",
            "config": {
              "type": "metric",
              "data_source": {
                "type": "data_view_spec",
                "index_pattern": "kibana_sample_data_logs",
                "time_field": "timestamp"
              },
              "metrics": [
                {
                  "type": "primary",
                  "operation": "average",
                  "field": "bytes"
                }
              ]
            }
          },
          {
            "grid": {
              "x": 24,
              "y": 5,
              "w": 24,
              "h": 10
            },
            "type": "vis",
            "config": {
              "type": "xy",
              "title": "Requests over time",
              "layers": [
                {
                  "type": "line",
                  "data_source": {
                    "type": "esql",
                    "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
                  },
                  "x": {
                    "column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
                  },
                  "y": [
                    {
                      "column": "count"
                    }
                  ]
                }
              ],
              "axis": {
                "x": {
                  "title": {
                    "visible": false
                  }

