SP=/tmp/claude-0/-tmp-eff-oz7fdihm-work/0536cbf5-c97a-5467-80bd-e50c5d30a2ce/scratchpad; mkdir -p "$SP"; cat > "$SP/dashboard.json" <<'EOF'
{
  "title": "EFF-9a937bda Web logs overview",
  "description": "Key traffic metrics from the Kibana sample web logs data.",
  "panels": [
    {
      "grid": {"x": 0, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Total requests",
        "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
        "metrics": [{"type": "primary", "operation": "count"}]
      }
    },
    {
      "grid": {"x": 12, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Unique client IPs",
        "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
        "metrics": [{"type": "primary", "operation": "unique_count", "field": "clientip"}]
      }
    },
    {
      "grid": {"x": 24, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "Average response size (bytes)",
        "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
        "metrics": [{"type": "primary", "operation": "average", "field": "bytes"}]
      }
    },
    {
      "grid": {"x": 36, "y": 0, "w": 12, "h": 6},
      "type": "vis",
      "config": {
        "type": "metric",
        "title": "5xx responses",
        "data_source": {"type": "data_view_reference", "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"},
        "query": {"language": "kuery", "query": "response.keyword >= \"500\" and response.keyword <= \"599\""},
        "metrics": [{"type": "primary", "operation": "count"}]
      }
    },
    {
      "grid": {"x": 0, "y": 6, "w": 48, "h": 12},
      "type": "vis",
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "layers": [
          {
            "type": "line",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
            },
            "x": {"column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
            "y": [{"column": "count"}]
          }
        ]
      }
    }
  ]
}
EOF
